#include "Proof_Parser.h"



bool Proof_Parser::lexAndParseFile(const char* filename) {
    if (!m_Proof_Lexer.lexFile(filename)) {
        printf("Proof_Parser::lexAndParseFile failed to lexFile(\"%s\")\n", filename);
        return false;
    }
    return parseTokenSequence();
}



